        Question(51073, "En quel année le skateboard est devenu un sport olympique?", listOf("2016", "2018", "2020", "2022"), 2, "Sport", Difficulty.HARD, explanation = "Le skateboard a fait ses débuts olympiques aux Jeux de Tokyo en 2021, mais l'édition était officiellement programmée pour 2020 avant d'être reportée en raison de la pandémie de Covid-19."),
