    private fun histoire(): List<Question> = listOf(
        Question(51251, "Quel empire africain a construit le Grande Zimbabwe?", listOf("Empire du Mali", "Empire du Songhaï", "Empire de Zimbabwe", "Aucun empire"), 3, "Histoire", Difficulty.EASY, explanation = "Le Grand Zimbabwe a été bâti par les ancêtres des Shonas entre le XIe et le XVe siècle, et non par un empire centralisé connu. Il s'agissait d'une cité-État prospère grâce au commerce de l'or et de l'ivoire."),
        Question(51252, "Quel est le plus ancien empire asiatique?", listOf("Empire Shang", "Empire Zhou", "Empire Qin", "Empire Han"), 0, "Histoire", Difficulty.MEDIUM, explanation = "L'empire Shang, qui a régné sur la vallée du fleuve Jaune du 16e au 11e siècle avant notre ère, est considéré comme la première dynastie chinoise historiquement attestée par des documents écrits et des artefacts archéologiques."),
        Question(51253, "Quel empire ottoman a conquis Constantinople en 1453?", listOf("Soliman le Magnifique", "Mehmed II", "Bayezid II", "Sélim Ier"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Mehmed II, surnommé le Conquérant, était le sultan ottoman qui a dirigé le siège victorieux de Constantinople en 1453, mettant fin à l'Empire byzantin."),
        Question(51254, "Quel être humain était l'homme fort des Vikings?", listOf("Ragnar Lothbrok", "Ivar le Désossé", "Erik le Rouge", "Leif Erikson"), 0, "Histoire", Difficulty.HARD, explanation = "Ragnar Lothbrok est un héros légendaire viking, dont les exploits sont racontés dans les sagas nordiques, souvent présenté comme un roi et un guerrier d'exception."),
        Question(51255, "Quel empire a construit Machu Picchu?", listOf("Empire Inca", "Empire Aztèque", "Empire Maya", "Empire Chibcha"), 0, "Histoire", Difficulty.EASY, explanation = "Machu Picchu a été érigé au XVe siècle sous le règne de l'empereur inca Pachacutec, servant de résidence royale et de site religieux."),
        Question(51256, "Quel est le plus long empire du monde?", listOf("Empire Romain", "Empire Byzantin", "Empire Chinois", "Empire Ottoman"), 2, "Histoire", Difficulty.HARD, explanation = "L'Empire chinois, sous différentes dynasties, a perduré de 221 av. J.-C. à 1912, soit plus de 2000 ans."),
        Question(51257, "Quel king d'Angleterre a signé la Magna Carta?", listOf("Richard Ier", "Jean sans Terre", "Henri III", "Édouard Ier"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Jean sans Terre a signé la Magna Carta en 1215 sous la pression des barons anglais, limitant son pouvoir royal."),
        Question(51258, "Quel roi de France a construit Versailles?", listOf("Louis XIII", "Louis XIV", "Louis XV", "Louis XVI"), 1, "Histoire", Difficulty.EASY, explanation = "Louis XIV, dit le Roi-Soleil, a fait construire le château de Versailles pour affirmer son pouvoir absolu et éloigner la noblesse de Paris."),
        Question(51259, "Quel est le plus ancien empire connu?", listOf("Empire Égyptien", "Empire Mésopotamien", "Empire Akkadien", "Empire Hittite"), 2, "Histoire", Difficulty.HARD, explanation = "L'Empire akkadien, fondé par Sargon d'Akkad vers 2334 av. J.-C., est considéré comme le premier empire de l'histoire en Mésopotamie. Il a unifié plusieurs cités-États sous une administration centrale."),
        Question(51260, "Quel continent a vu la révolution industrielle d'abord?", listOf("Asie", "Amérique du Nord", "Europe", "Afrique"), 2, "Histoire", Difficulty.EASY, explanation = "La révolution industrielle a débuté en Grande-Bretagne au XVIIIe siècle avant de s'étendre au reste de l'Europe. Ce continent a été le berceau des premières innovations mécaniques et de l'industrialisation."),
        Question(51261, "Quel pays a eu la première révolution industrielle?", listOf("France", "Allemagne", "Grande-Bretagne", "Hollande"), 2, "Histoire", Difficulty.MEDIUM, explanation = "La Grande-Bretagne a été le berceau de la première révolution industrielle grâce à ses innovations technologiques, ses ressources en charbon et fer, et son contexte économique favorable au XVIIIe siècle."),
        Question(51262, "Quel est le pays le plus ancien encore en existence?", listOf("Japon", "Égypte", "Vatican", "Chine"), 3, "Histoire", Difficulty.HARD, explanation = "La Chine est considérée comme l'une des plus anciennes civilisations continues au monde, avec des archives historiques remontant à plus de 3 500 ans sous la dynastie Shang."),
        Question(51263, "Quel est le plus grand empire à la surface de la terre?", listOf("Empire Britannique", "Empire Russe", "Empire Mongol", "Empire Ottoman"), 0, "Histoire", Difficulty.HARD, explanation = "À son apogée au début du XXe siècle, l'Empire britannique contrôlait environ un quart des terres émergées et de la population mondiale."),
        Question(51264, "Quel roi d'Angleterre a réalisé la Norman Conquest?", listOf("Guillaume le Conquérant", "Henri VIII", "Richard Cœur de Lion", "Jean sans Terre"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Guillaume, duc de Normandie, a conquis l'Angleterre en 1066 après sa victoire à la bataille d'Hastings, devenant ainsi roi sous le nom de Guillaume Ier."),
        Question(51265, "Quel est l'empire asiatique le plus influent?", listOf("Empire Ottomane", "Empire Perse", "Empire Mongol", "Empire Indien"), 2, "Histoire", Difficulty.HARD, explanation = "Fondé par Gengis Khan au XIIIe siècle, l'Empire mongol est devenu le plus vaste empire contigu de l'histoire, reliant l'Asie et l'Europe et facilitant les échanges culturels et commerciaux."),
        Question(51266, "Quel roi a dirigé la Révolution Française?", listOf("Louis XV", "Louis XVI", "Louis XVII", "Louis XVIII"), 1, "Histoire", Difficulty.EASY, explanation = "Louis XVI était le roi de France au début de la Révolution française en 1789. Il a été renversé et exécuté en 1793, marquant la fin de la monarchie absolue."),
        Question(51267, "Quel est l'empire africain le plus puissant?", listOf("Mali", "Songhaï", "Kanem-Bornou", "Axoum"), 0, "Histoire", Difficulty.HARD, explanation = "L'empire du Mali, sous le règne de Mansa Moussa au XIVe siècle, contrôlait d'immenses richesses en or et dominait le commerce transsaharien."),
        Question(51268, "Quel est le plus grand empire à jamais exister?", listOf("Empire Britannique", "Empire Russe", "Empire Mongol", "Empire Austro-Hongrois"), 2, "Histoire", Difficulty.HARD, explanation = "L'Empire Mongol est considéré comme le plus vaste empire contigu de l'histoire, s'étendant de l'Asie de l'Est à l'Europe de l'Est au XIIIe siècle sous la direction de Gengis Khan et ses successeurs."),
        Question(51269, "Quel est l'empire asiatique le plus ancien?", listOf("Empire Persan", "Empire Aryen", "Empire Assyrien", "Empire Hittite"), 1, "Histoire", Difficulty.HARD, explanation = "L'Empire aryen, établi vers 1500 av. J.-C. en Inde, est considéré comme le plus ancien empire asiatique connu, précédant les dynasties chinoises et mésopotamiennes."),
        Question(51270, "Quel est l'empire africain le plus ancien?", listOf("Axoum", "Égypte Ancienne", "Kouche", "Aucun"), 3, "Histoire", Difficulty.HARD, explanation = "La question est piégée car il n'existe pas d'empire africain unique considéré comme le plus ancien ; les premiers grands royaumes comme Koush ou l'Égypte antique sont souvent classés comme des royaumes ou civilisations, pas des empires au sens strict."),
        Question(51271, "Quel roi de Prusse a créé l'Empire Allemand?", listOf("Frédéric le Grand", "Frédéric Guillaume", "Frédéric Guillaume III", "Frédéric Guillaume IV"), 0, "Histoire", Difficulty.HARD, explanation = "C'est en réalité Guillaume Ier, roi de Prusse, qui a proclamé l'Empire allemand en 1871, tandis que Frédéric le Grand a régné au XVIIIe siècle et modernisé la Prusse sans créer d'empire."),
        Question(51272, "Quel est l'empire ottoman le plus puissant?", listOf("Soliman le Magnifique", "Bayezid II", "Sélim Ier", "Mehmed II"), 0, "Histoire", Difficulty.HARD, explanation = "Soliman le Magnifique a régné au XVIe siècle, période où l'Empire ottoman a atteint son apogée territorial et culturel, s'étendant de la Hongrie à l'Afrique du Nord."),
        Question(51273, "Quel est le plus grand explorateur africain?", listOf("David Livingstone", "Henry Morton Stanley", "Mungo Park", "Aucun"), 3, "Histoire", Difficulty.HARD, explanation = "Le terme \"explorateur\" est historiquement associé aux récits coloniaux européens, et l'Afrique a sa propre histoire riche de voyages et de découvertes internes, rendant toute désignation unique réductrice."),
        Question(51274, "Quel est l'empire asiatique le plus influent du XVIIIe siècle?", listOf("Empire Chinois", "Empire Indien", "Empire Persan", "Empire Mongol"), 0, "Histoire", Difficulty.HARD, explanation = "L'Empire chinois, sous la dynastie Qing, dominait l'Asie au XVIIIe siècle grâce à son expansion territoriale et son influence économique et culturelle."),
        Question(51275, "Quel est le plus grand explorateur américain?", listOf("Christophe Colomb", "Vasco de Balboa", "Fernand de Magellan", "Hernán Cortés"), 0, "Histoire", Difficulty.HARD, explanation = "Christophe Colomb, navigateur génois au service de l'Espagne, est considéré comme le plus grand explorateur américain pour avoir ouvert la voie à la colonisation européenne des Amériques en 1492."),
        Question(51276, "Quel est l'empire asiatique le plus ancien du XVIIe siècle?", listOf("Empire Moghol", "Empire Persan", "Empire Chinois", "Empire Japonais"), 2, "Histoire", Difficulty.HARD, explanation = "L'Empire chinois, sous la dynastie Ming puis Qing, existait déjà depuis plusieurs siècles au XVIIe siècle, ce qui en fait l'empire asiatique le plus ancien de cette époque."),
        Question(51277, "Quel est le plus grand explorateur asiatique?", listOf("Zheng He", "Marco Polo", "Christophe Colomb", "Vasco da Gama"), 0, "Histoire", Difficulty.HARD, explanation = "Zheng He a mené sept expéditions navales majeures entre 1405 et 1433 pour la dynastie Ming, atteignant l'Afrique de l'Est et l'Asie du Sud-Est."),
        Question(51278, "Quel est l'empire asiatique le plus puissant du XIXe siècle?", listOf("Empire Chinois", "Empire Indien", "Empire Persan", "Empire Japonais"), 0, "Histoire", Difficulty.HARD, explanation = "L'Empire chinois, sous la dynastie Qing, était le plus vaste et peuplé d'Asie au XIXe siècle, dominant économiquement et culturellement la région malgré un déclin progressif face aux puissances occidentales."),
        Question(51279, "Quel est le plus grand explorateur européen?", listOf("Christophe Colomb", "Vasco da Gama", "Fernand de Magellan", "Marco Polo"), 0, "Histoire", Difficulty.HARD, explanation = "Christophe Colomb est souvent considéré comme le plus grand explorateur européen pour avoir ouvert la voie à la colonisation des Amériques en 1492 sous le patronage des Rois catholiques espagnols."),
        Question(51280, "Quel est l'empire asiatique le plus important du XXe siècle?", listOf("Empire Britannique", "Empire Japonais", "Empire Français", "Empire Allemand"), 0, "Histoire", Difficulty.HARD, explanation = "L'Empire britannique, bien que centré sur l'Europe, a dominé de vastes territoires asiatiques comme l'Inde, la Birmanie et la Malaisie, ce qui en fait la puissance impériale la plus influente du XXe siècle en Asie."),
        Question(51281, "Quel est le plus grand explorateur océanique?", listOf("James Cook", "Christophe Colomb", "Vasco da Gama", "Ferdinand Magellan"), 0, "Histoire", Difficulty.HARD, explanation = "James Cook a mené trois grandes expéditions dans le Pacifique, cartographiant des territoires comme la Nouvelle-Zélande et la côte est de l'Australie. Ses voyages ont considérablement élargi la connaissance européenne des océans."),
        Question(51282, "Quel est l'empire africain le plus puissant du XIIIe siècle?", listOf("Mali", "Songhaï", "Kanem-Bornou", "Benin"), 0, "Histoire", Difficulty.HARD, explanation = "Sous le règne de Soundiata Keita, l'Empire du Mali a dominé l'Afrique de l'Ouest au XIIIe siècle grâce à sa puissance militaire et au contrôle des routes commerciales de l'or et du sel."),
        Question(51283, "Quel est le plus grand explorateur polaire?", listOf("Roald Amundsen", "Robert Falcon Scott", "Ernest Shackleton", "Fridtjof Nansen"), 0, "Histoire", Difficulty.HARD, explanation = "Roald Amundsen mena la première expédition à atteindre le pôle Sud en 1911 et fut aussi le premier à franchir le passage du Nord-Ouest."),
        Question(51284, "Quel est l'empire africain le plus puissant du XVIe siècle?", listOf("Mali", "Songhaï", "Kanem-Bornou", "Bénin"), 1, "Histoire", Difficulty.HARD, explanation = "L'empire Songhaï, sous le règne d'Askia Mohammed, dominait l'Afrique de l'Ouest au XVIe siècle grâce à son contrôle des routes commerciales transsahariennes et à sa capitale Tombouctou, centre intellectuel et économique."),
        Question(51285, "Quel est le plus grand explorateur montagnard?", listOf("Edmund Hillary", "Tenzing Norgay", "Reinhold Messner", "Aucun"), 3, "Histoire", Difficulty.HARD, explanation = "L'expression \"plus grand explorateur montagnard\" est subjective et ne correspond à aucun titre officiel ou record universellement reconnu. Aucun explorateur ne peut être objectivement désigné comme tel."),
        Question(51286, "Quel est l'empire asiatique le plus important du XIIe siècle?", listOf("Empire Moghol", "Empire Khmer", "Empire Angkor", "Empire Seljuk"), 0, "Histoire", Difficulty.HARD, explanation = "L'Empire moghol n'a été fondé qu'au XVIe siècle par Babur. Au XIIe siècle, l'empire asiatique le plus important était l'Empire mongol, dirigé par Gengis Khan."),
        Question(51287, "Quel est le plus grand explorateur souterrain?", listOf("William Buckland", "Édouard-Alfred Martel", "Charles Darwin", "Aucun"), 1, "Histoire", Difficulty.HARD, explanation = "Édouard-Alfred Martel est considéré comme le père de la spéléologie moderne pour ses explorations systématiques des grottes et gouffres au XIXe siècle."),
        Question(51288, "Quel est l'empire africain le plus puissant du Xe siècle?", listOf("Égypte Fatimide", "Axoum", "Mali", "Songhaï"), 0, "Histoire", Difficulty.HARD, explanation = "L'Égypte fatimide, fondée en 969, dominait le Xe siècle grâce à sa puissance militaire, son contrôle des routes commerciales et son rayonnement culturel, rivalisant avec les califats abbasside et omeyyade."),
        Question(51289, "Quel est le plus grand explorateur marin?", listOf("Christophe Colomb", "Vasco da Gama", "Fernand de Magellan", "James Cook"), 3, "Histoire", Difficulty.HARD, explanation = "James Cook a mené trois grandes expéditions dans l'océan Pacifique, cartographiant des territoires comme la Nouvelle-Zélande et la côte est de l'Australie, ce qui en fait l'un des explorateurs marins les plus influents."),
        Question(51290, "Quel est l'empire asiatique le plus important du IXe siècle?", listOf("Empire Khmer", "Empire Pala", "Empire Carolingien", "Empire Arabe"), 1, "Histoire", Difficulty.HARD, explanation = "L'Empire Pala dominait l'Inde orientale et le Bengale au IXe siècle, étant une puissance majeure en Asie grâce à son influence culturelle et militaire."),
        Question(51291, "Quel est le plus grand explorateur astral?", listOf("Yuri Gagarin", "Neil Armstrong", "Buzz Aldrin", "John Glenn"), 1, "Histoire", Difficulty.HARD, explanation = "Neil Armstrong est le premier humain à avoir marché sur la Lune le 20 juillet 1969 lors de la mission Apollo 11, ce qui en fait l'explorateur astral le plus célèbre."),
        Question(51292, "Quel est l'empire africain le plus puissant du VIIIe siècle?", listOf("Axoum", "Nubie", "Égypte", "Mali"), 0, "Histoire", Difficulty.HARD, explanation = "L'empire d'Axoum, situé dans l'actuelle Éthiopie et l'Érythrée, dominait le commerce en mer Rouge et contrôlait des routes vers l'Afrique et l'Asie au VIIIe siècle."),
        Question(51293, "Quel est le plus grand explorateur spatial?", listOf("Yuri Gagarin", "Sergei Korolev", "Wernher von Braun", "Vitaly Zholobov"), 2, "Histoire", Difficulty.HARD, explanation = "Wernher von Braun est considéré comme le plus grand explorateur spatial pour avoir conçu la fusée Saturn V qui a permis les missions Apollo vers la Lune."),
        Question(51294, "Quel est l'empire asiatique le plus important du VIIe siècle?", listOf("Empire Tang", "Empire Umayyade", "Empire Sassanide", "Empire Byzantin"), 0, "Histoire", Difficulty.HARD, explanation = "L'Empire Tang, fondé en 618, dominait l'Asie orientale au VIIe siècle grâce à sa puissance militaire, son expansion territoriale et son influence culturelle majeure."),
        Question(51295, "Quel est le plus grand explorateur du premier siècle?", listOf("Alexandre le Grand", "Zénon", "Anaxagore", "Aucun"), 0, "Histoire", Difficulty.HARD, explanation = "Alexandre le Grand a mené des conquêtes jusqu'en Inde au IVe siècle av. J.-C., ce qui en fait l'un des plus grands explorateurs et conquérants de l'Antiquité."),
        Question(51296, "Quel est l'empire africain le plus puissant du VIe siècle?", listOf("Axoum", "Égypte", "Nubie", "Kanem-Bornou"), 0, "Histoire", Difficulty.HARD, explanation = "L’empire d’Axoum, situé dans l’actuelle Éthiopie, contrôlait les routes commerciales entre l’Afrique, l’Arabie et l’Inde, ce qui en faisait la puissance dominante en Afrique au VIe siècle."),
        Question(51297, "Quel est le plus grand explorateur du deuxième siècle?", listOf("Crésias de Cnide", "Pausanias", "Strabon", "Aucun"), 3, "Histoire", Difficulty.HARD, explanation = "Le terme \"explorateur\" est une notion moderne qui n'existait pas au IIe siècle, et les voyages de découverte de cette époque étaient souvent militaires ou commerciaux, sans figure individuelle marquante."),
        Question(51298, "Quel est l'empire asiatique le plus important du Ve siècle?", listOf("Empire Gupta", "Empire Sassanide", "Empire Byzantin", "Empire Romain d'Orient"), 0, "Histoire", Difficulty.HARD, explanation = "L'Empire Gupta dominait le sous-continent indien au Ve siècle, marquant un âge d'or culturel et scientifique. Son influence s'étendait sur l'Inde du Nord, avec une administration centralisée et des avancées majeures en mathématiques et astronomie."),
        Question(51299, "Quel est le plus grand explorateur du premier millénaire?", listOf("Marc Polo", "Christophe Colomb", "Vasco da Gama", "Bartolomeu Dias"), 0, "Histoire", Difficulty.HARD, explanation = "Marco Polo, marchand vénitien du XIIIe siècle, est célèbre pour ses voyages en Asie et son récit détaillé de la cour de Kubilai Khan, qui a ouvert la connaissance de l'Orient à l'Europe médiévale."),
        Question(51300, "Quel est l'empire africain le plus puissant du IVe siècle?", listOf("Axoum", "Égypte", "Nubie", "Mali"), 0, "Histoire", Difficulty.HARD, explanation = "L'empire d'Axoum, situé dans l'actuelle Éthiopie et Érythrée, dominait le commerce en mer Rouge et contrôlait des routes vers l'Inde et Rome.")
    )

    private fun science(): List<Question> = listOf(
        Question(51301, "Quel scientifique a reçu le prix Nobel de Physique en 2021?", listOf("Giorgio Parisi", "Syukuro Manabe", "Klaus Hasselmann", "Tous les trois"), 3, "Science", Difficulty.MEDIUM, explanation = "Le prix Nobel de physique 2021 a été attribué conjointement à Syukuro Manabe, Klaus Hasselmann et Giorgio Parisi pour leurs travaux sur la modélisation du climat terrestre et les systèmes complexes."),
        Question(51302, "Quel est le plus grand nombre de prix Nobel reçus par une seule personne?", listOf("1", "2", "3", "4"), 1, "Science", Difficulty.HARD, explanation = "Aucune personne n'a reçu plus de deux prix Nobel. Marie Curie (physique et chimie), Linus Pauling (chimie et paix) et John Bardeen (physique à deux reprises) en sont les exemples."),
        Question(51303, "Quel domaine a été le premier à recevoir le prix Nobel?", listOf("Physique", "Chimie", "Littérature", "Paix"), 0, "Science", Difficulty.EASY, explanation = "Le prix Nobel a été créé en 1901, et la première cérémonie a décerné les récompenses dans les cinq domaines originaux, dont la physique. Alfred Nobel avait défini cette catégorie dans son testament."),
        Question(51304, "Quel scientifique a découvert la structure de l'ADN?", listOf("Watson et Crick", "Franklin", "Wilkins", "Tous les trois"), 3, "Science", Difficulty.EASY, explanation = "James Watson, Francis Crick et Rosalind Franklin ont tous contribué à la découverte de la structure en double hélice de l'ADN en 1953, bien que le prix Nobel n'ait été attribué qu'à Watson et Crick."),
        Question(51305, "Quel élément chimique est le plus rare dans l'univers?", listOf("Technétium", "Prométhium", "Ténessine", "Livermorium"), 2, "Science", Difficulty.HARD, explanation = "Le ténessine est un élément synthétique produit en laboratoire, avec une demi-vie très courte, ce qui le rend extrêmement rare dans l'univers."),
        Question(51306, "Quel est le plus grand télescope spatial jamais lancé?", listOf("Hubble", "James Webb", "Spitzer", "Planck"), 1, "Science", Difficulty.MEDIUM, explanation = "Le télescope spatial James Webb, lancé en décembre 2021, est le plus grand et le plus puissant jamais déployé, avec un miroir principal de 6,5 mètres de diamètre."),
        Question(51307, "Quel est le plus récent prix Nobel de Physique?", listOf("2021", "2022", "2023", "2024"), 3, "Science", Difficulty.MEDIUM, explanation = "Le prix Nobel de physique 2024 a été attribué à John Hopfield et Geoffrey Hinton pour leurs travaux fondateurs sur les réseaux de neurones artificiels."),
        Question(51308, "Quel scientifique a découvert le neutrino?", listOf("Wolfgang Pauli", "Enrico Fermi", "Ettore Majorana", "Aucun"), 0, "Science", Difficulty.HARD, explanation = "Wolfgang Pauli a postulé l'existence du neutrino en 1930 pour expliquer la conservation de l'énergie dans la désintégration bêta, une particule neutre et de masse quasi nulle."),
        Question(51309, "Quel est le plus puissant microscope jamais créé?", listOf("Électronique", "Optique", "À force atomique", "À tunnel"), 2, "Science", Difficulty.HARD, explanation = "Le microscope à force atomique utilise une sonde pour sonder la surface des matériaux à l'échelle atomique, offrant une résolution bien supérieure aux microscopes optiques ou électroniques classiques."),
        Question(51310, "Quel scientifique a découvert l'antimatière?", listOf("Paul Dirac", "Carl Anderson", "Subrahmanyan Chandrasekhar", "Aucun"), 0, "Science", Difficulty.HARD, explanation = "Paul Dirac a prédit l'existence de l'antimatière en 1928 par son équation de la mécanique quantique, ce qui lui a valu le prix Nobel de physique en 1933."),
        Question(51311, "Quel est le plus grand accélérateur de particules?", listOf("Fermilab", "CERN", "SLAC", "KEK"), 1, "Science", Difficulty.EASY, explanation = "Le CERN abrite le Grand collisionneur de hadrons (LHC), le plus grand et le plus puissant accélérateur de particules au monde, situé près de Genève."),
        Question(51313, "Quel est le plus grand génome jamais séquencé?", listOf("Humain", "Chimpanzé", "Éléphant", "Paris Japonica"), 3, "Science", Difficulty.HARD, explanation = "Le génome de la plante Paris japonica, une herbacée vivace, détient le record avec environ 150 milliards de paires de bases, soit 50 fois plus que le génome humain."),
        Question(51314, "Quel scientifique a découvert le photon?", listOf("Albert Einstein", "Max Planck", "Niels Bohr", "Aucun"), 1, "Science", Difficulty.HARD, explanation = "Max Planck a introduit le concept de quantum d'énergie en 1900, posant les bases de la mécanique quantique. C'est Albert Einstein qui a ensuite théorisé le photon comme particule de lumière en 1905."),
        Question(51315, "Quel est le plus grand problème non résolu en physique?", listOf("Gravité quantique", "Matière noire", "Énergie noire", "Tous les trois"), 3, "Science", Difficulty.HARD, explanation = "La physique contemporaine bute sur trois problèmes majeurs : la matière noire, l'énergie noire et l'incompatibilité entre la relativité générale et la mécanique quantique. Aucun n'a encore de solution complète, ce qui les place tous au même niveau."),
        Question(51316, "Quel scientifique a découvert le quark?", listOf("Murray Gell-Mann", "George Zweig", "James Bjorken", "Aucun"), 0, "Science", Difficulty.HARD, explanation = "Murray Gell-Mann a proposé l'existence des quarks en 1964 pour expliquer la composition des hadrons, une découverte qui lui a valu le prix Nobel de physique en 1969."),
        Question(51317, "Quel est le plus grand nombre d'atomes jamais comptés?", listOf("10^15", "10^20", "10^30", "Infini"), 2, "Science", Difficulty.HARD, explanation = "Le nombre 10^30 correspond à une estimation du nombre d'atomes dans l'univers observable, un calcul théorique basé sur la densité et le volume cosmiques. Aucun comptage direct n'est possible, cette valeur reste une approximation scientifique."),
        Question(51318, "Quel scientifique a découvert le boson de Higgs?", listOf("Peter Higgs", "François Englert", "CERN", "Tous les trois"), 3, "Science", Difficulty.MEDIUM, explanation = "Le boson de Higgs a été théorisé en 1964 par Peter Higgs, Robert Brout et François Englert. La découverte expérimentale en 2012 au CERN a confirmé leurs travaux communs."),
        Question(51319, "Quel est le plus grand nombre de dimensions théoriques?", listOf("4", "10", "11", "26"), 3, "Science", Difficulty.HARD, explanation = "En théorie des cordes, les équations mathématiques nécessitent 26 dimensions pour être cohérentes dans le cadre de la théorie bosonique."),
        Question(51320, "Quel scientifique a découvert les ondes gravitationnelles?", listOf("Albert Einstein", "LIGO", "Virgo", "Tous les trois"), 1, "Science", Difficulty.MEDIUM, explanation = "La collaboration LIGO a annoncé la première détection directe des ondes gravitationnelles en 2016, confirmant une prédiction d'Einstein."),
        Question(51321, "Quel est le plus grand changement climatique jamais enregistré?", listOf("Extinction KT", "Snowball Earth", "Grand Oxydation", "Aucun"), 1, "Science", Difficulty.HARD, explanation = "Snowball Earth désigne une période où la planète était presque entièrement recouverte de glace, il y a environ 700 millions d'années, représentant le plus grand changement climatique connu."),
        Question(51322, "Quel scientifique a découvert la sélection naturelle?", listOf("Charles Darwin", "Alfred Wallace", "Gregor Mendel", "Aucun"), 0, "Science", Difficulty.EASY, explanation = "Charles Darwin a formulé la théorie de l'évolution par sélection naturelle après ses observations lors du voyage du Beagle, notamment aux îles Galápagos."),
        Question(51323, "Quel est le plus grand nombre de gènes chez un être humain?", listOf("20,000", "30,000", "60,000", "100,000"), 0, "Science", Difficulty.HARD, explanation = "Le nombre de gènes codant pour des protéines chez l'humain est estimé à environ 20 000, bien moins que les 100 000 supposés avant le séquençage du génome humain."),
        Question(51324, "Quel scientifique a découvert le virus du SIDA?", listOf("Luc Montagnier", "Robert Gallo", "Jean-Claude Chermann", "Tous les trois"), 3, "Science", Difficulty.MEDIUM, explanation = "Le virus du SIDA (VIH) a été identifié en 1983 par deux équipes distinctes : celle de Luc Montagnier à l'Institut Pasteur et celle de Robert Gallo aux États-Unis, ce qui a conduit à une reconnaissance partagée de la découverte."),
        Question(51325, "Quel est le plus grand nombre de microbes dans le corps humain?", listOf("100", "1000", "1 trillion", "100 trillion"), 3, "Science", Difficulty.HARD, explanation = "Le corps humain abrite environ 100 000 milliards de microbes, principalement dans l'intestin, dépassant largement le nombre de nos propres cellules."),
        Question(51326, "Quel scientifique a découvert le vaccin contre la rage?", listOf("Louis Pasteur", "Edward Jenner", "Jonas Salk", "Aucun"), 0, "Science", Difficulty.MEDIUM, explanation = "Louis Pasteur a développé le premier vaccin contre la rage en 1885, en utilisant des virus atténués. Ce succès a marqué une avancée majeure dans la lutte contre les maladies infectieuses."),
        Question(51327, "Quel est le plus grand nombre de planètes dans une système solaire?", listOf("8", "12", "50", "100"), 2, "Science", Difficulty.HARD, explanation = "Le système solaire de Kepler-90 possède huit planètes, comme le nôtre, mais des simulations suggèrent que certains systèmes pourraient en compter jusqu'à 50, bien qu'aucun n'ait été observé."),
        Question(51328, "Quel scientifique a découvert le vaccin contre la polio?", listOf("Jonas Salk", "Albert Sabin", "Edward Jenner", "Aucun"), 0, "Science", Difficulty.MEDIUM, explanation = "Jonas Salk a développé le premier vaccin efficace contre la polio en 1955, en utilisant un virus inactivé. Son travail a permis de réduire massivement les épidémies de cette maladie paralysante."),
        Question(51329, "Quel est le plus grand nombre de lunes chez une planète?", listOf("79", "92", "146", "200"), 1, "Science", Difficulty.HARD, explanation = "Jupiter détient le record avec 92 lunes confirmées, dépassant Saturne qui en compte 83. Ce nombre inclut les petites lunes irrégulières découvertes récemment."),
        Question(51330, "Quel scientifique a découvert l'insuline?", listOf("Frederick Banting", "Charles Best", "John MacLeod", "Tous les trois"), 3, "Science", Difficulty.HARD, explanation = "Frederick Banting, Charles Best et James Collip ont collaboré à l'isolement et à la purification de l'insuline en 1921-1922, menant à son utilisation clinique contre le diabète."),
        Question(51331, "Quel est le plus grand nombre de trous noirs connus?", listOf("1", "millions", "milliards", "infini"), 2, "Science", Difficulty.HARD, explanation = "Les astronomes estiment qu'il existe des milliards de trous noirs dans l'univers observable, dont la plupart sont des trous noirs stellaires."),
        Question(51332, "Quel scientifique a découvert les rayons X?", listOf("Wilhelm Röntgen", "Henry Becquerel", "Pierre Curie", "Aucun"), 0, "Science", Difficulty.EASY, explanation = "Wilhelm Röntgen a découvert les rayons X en 1895, ce qui lui a valu le premier prix Nobel de physique en 1901."),
        Question(51333, "Quel est le plus grand nombre d'espèces découvertes?", listOf("1 million", "5 millions", "10 millions", "100 millions"), 2, "Science", Difficulty.HARD, explanation = "On estime qu'environ 10 millions d'espèces vivent sur Terre, mais seulement 1,5 à 2 millions ont été formellement décrites par la science."),
        Question(51334, "Quel scientifique a découvert les gènes?", listOf("Gregor Mendel", "Charles Darwin", "Francis Galton", "Aucun"), 0, "Science", Difficulty.MEDIUM, explanation = "Gregor Mendel, moine et botaniste autrichien du XIXe siècle, a établi les lois de l'hérédité en étudiant les pois, posant ainsi les bases de la génétique moderne."),
        Question(51335, "Quel est le plus grand nombre de cromosomes chez un être vivant?", listOf("46", "62", "260", "500"), 2, "Science", Difficulty.HARD, explanation = "Le nombre record de 260 chromosomes est détenu par une fougère appelée Ophioglossum reticulatum, bien loin des 46 chromosomes humains."),
        Question(51336, "Quel scientifique a découvert le fluor?", listOf("Humphry Davy", "André-Marie Ampère", "Claude Gay-Lussac", "Aucun"), 0, "Science", Difficulty.HARD, explanation = "Humphry Davy a isolé le fluor en 1813 en utilisant l'électrolyse, bien que le gaz pur n'ait été obtenu qu'en 1886 par Henri Moissan."),
        Question(51337, "Quel est le plus grand nombre de synapse chez un cerveau humain?", listOf("1 milliard", "10 milliards", "100 milliards", "1 trillion"), 3, "Science", Difficulty.HARD, explanation = "Le cerveau humain contient environ 100 milliards de neurones, et chaque neurone peut avoir des milliers de connexions, ce qui porte le total des synapses à environ 1 trillion. Ce chiffre illustre la complexité extrême du réseau neuronal."),
        Question(51338, "Quel scientifique a découvert le néon?", listOf("William Ramsay", "Morris William Travers", "Baron Rayleigh", "Aucun"), 0, "Science", Difficulty.HARD, explanation = "William Ramsay a découvert le néon en 1898 avec Morris Travers en distillant de l'air liquide."),
        Question(51339, "Quel est le plus grand nombre de cellules dans le corps humain?", listOf("1 million", "1 milliard", "37 milliards", "200 milliards"), 2, "Science", Difficulty.HARD, explanation = "Le corps humain adulte contient environ 37 000 milliards de cellules, une estimation basée sur des études de biologie cellulaire. Ce nombre varie selon l'âge, la taille et la méthode de calcul."),
        Question(51340, "Quel scientifique a découvert le platine?", listOf("Juan José d'Ulloa", "Charles Wood", "Aucun", "Jules Verne"), 2, "Science", Difficulty.HARD, explanation = "Le platine est connu et utilisé depuis l'Antiquité par les civilisations précolombiennes, mais il n'a pas été découvert par un scientifique unique en Europe avant d'être identifié comme un nouvel élément au XVIIIe siècle."),
        Question(51341, "Quel est le plus grand nombre de protéines dans le corps humain?", listOf("1000", "10 000", "100 000", "1 million"), 2, "Science", Difficulty.HARD, explanation = "Le corps humain exprime environ 100 000 protéines différentes, issues de l'expression de ses gènes, bien que le nombre exact varie selon les études."),
        Question(51342, "Quel scientifique a découvert le carbonne?", listOf("Antoine Lavoisier", "Aucun", "Johannes Döbereiner", "Humphry Davy"), 1, "Science", Difficulty.HARD, explanation = "Le carbone est un élément connu depuis l'Antiquité, notamment sous forme de charbon et de diamant, et n'a donc pas été « découvert » par un scientifique spécifique."),
        Question(51343, "Quel est le plus grand nombre de bactéries dans le corps humain?", listOf("1 million", "1 milliard", "100 milliards", "100 trillions"), 3, "Science", Difficulty.HARD, explanation = "Le corps humain abrite environ 100 000 milliards de bactéries, principalement dans l'intestin, ce qui dépasse largement le nombre de nos propres cellules."),
        Question(51344, "Quel scientifique a découvert l'azote?", listOf("Daniel Rutherford", "Carl Wilhelm Scheele", "Joseph Priestley", "Aucun"), 0, "Science", Difficulty.HARD, explanation = "Daniel Rutherford, médecin et chimiste écossais, isola l'azote en 1772 en retirant l'oxygène et le dioxyde de carbone de l'air."),
        Question(51345, "Quel est le plus grand nombre de virus dans le corps humain?", listOf("1000", "1 million", "100 milliards", "1 trillion"), 2, "Science", Difficulty.HARD, explanation = "Le corps humain abrite environ 100 milliards de virus, principalement dans le microbiome intestinal, où ils jouent un rôle dans la régulation des bactéries et du système immunitaire."),
        Question(51346, "Quel scientifique a découvert l'oxygène?", listOf("Joseph Priestley", "Carl Wilhelm Scheele", "Antoine Lavoisier", "Aucun"), 2, "Science", Difficulty.MEDIUM, explanation = "Antoine Lavoisier a identifié et nommé l'oxygène en 1778, démontrant son rôle dans la combustion et la respiration, ce qui a révolutionné la chimie en renversant la théorie du phlogistique."),
        Question(51347, "Quel est le plus grand nombre de mitochondries dans une cellule?", listOf("10", "100", "1000", "10 000"), 3, "Science", Difficulty.HARD, explanation = "Les cellules ayant les plus forts besoins énergétiques, comme les cellules musculaires ou hépatiques, peuvent contenir jusqu'à 10 000 mitochondries."),
        Question(51348, "Quel scientifique a découvert l'hydrogène?", listOf("Henry Cavendish", "Carl Wilhelm Scheele", "Joseph Priestley", "Aucun"), 0, "Science", Difficulty.HARD, explanation = "Henry Cavendish a isolé et identifié l'hydrogène en 1766 lors d'expériences sur des métaux et des acides, le nommant \"air inflammable\"."),
        Question(51349, "Quel est le plus grand nombre de ribosomes dans une cellule?", listOf("100", "1000", "10 000", "100 000"), 2, "Science", Difficulty.HARD, explanation = "Les ribosomes sont des organites essentiels à la synthèse des protéines, et une cellule peut en contenir jusqu'à 10 000, notamment dans les cellules très actives comme les hépatocytes."),
        Question(51350, "Quel scientifique a découvert le cuivre?", listOf("Aucun (naturel)", "Johannes Döbereiner", "Humphry Davy", "Antoine Lavoisier"), 0, "Science", Difficulty.MEDIUM, explanation = "Le cuivre est connu et utilisé par l'humanité depuis la préhistoire, bien avant l'émergence de la science moderne, donc aucun scientifique spécifique n'en est le découvreur.")
    )

    private fun geographie(): List<Question> = listOf(
        Question(51351, "Quel est le plus grand pays d'Afrique?", listOf("Égypte", "Algérie", "Nigeria", "Soudan"), 1, "Géographie", Difficulty.EASY, explanation = "L'Algérie est le plus grand pays d'Afrique avec une superficie d'environ 2,38 millions de kilomètres carrés, dépassant la République démocratique du Congo et le Soudan."),
        Question(51353, "Quel est le plus grand pays d'Asie?", listOf("Russie", "Chine", "Inde", "Kazakhstan"), 0, "Géographie", Difficulty.EASY, explanation = "La Russie est le plus grand pays du monde, et sa partie asiatique, la Sibérie, représente environ 77% de son territoire, ce qui en fait le plus grand pays d'Asie."),
        Question(51354, "Quel est le pays africain le plus peuplé?", listOf("Égypte", "Éthiopie", "Nigeria", "Congo"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Le Nigeria est le pays le plus peuplé d'Afrique avec plus de 200 millions d'habitants, dépassant largement l'Éthiopie et l'Égypte."),
        Question(51355, "Quel est le plus grand océan?", listOf("Atlantique", "Indien", "Pacifique", "Arctique"), 2, "Géographie", Difficulty.EASY, explanation = "L'océan Pacifique est le plus vaste et le plus profond des océans, couvrant environ un tiers de la surface terrestre."),
        Question(51356, "Quel est le plus haut sommet d'Afrique?", listOf("Mont Kenya", "Kilimandjaro", "Atlas", "Rwenzori"), 1, "Géographie", Difficulty.EASY, explanation = "Le Kilimandjaro, situé en Tanzanie, culmine à 5 895 mètres, ce qui en fait le point le plus élevé du continent africain."),
        Question(51359, "Quel est le pays sans accès à la mer?", listOf("Bolivie", "Lesotho", "Ouganda", "Tous les trois"), 3, "Géographie", Difficulty.MEDIUM, explanation = "Les trois pays proposés dans la question (par exemple l'Ouzbékistan, le Liechtenstein et le Paraguay) sont tous des États enclavés, sans accès direct à un océan."),
        Question(51361, "Quel est le pays île le plus grand d'Afrique?", listOf("Madagascar", "Zanzibar", "Île Maurice", "Seychelles"), 0, "Géographie", Difficulty.HARD, explanation = "Madagascar est la plus grande île d'Afrique et la quatrième du monde, située dans l'océan Indien au large de la côte mozambicaine."),
        Question(51366, "Quel est le désert le plus grand d'Afrique?", listOf("Sahara", "Kalahari", "Namib", "Tanami"), 0, "Géographie", Difficulty.EASY, explanation = "Le Sahara s'étend sur environ 9,2 millions de kilomètres carrés, couvrant une grande partie de l'Afrique du Nord, ce qui en fait le plus vaste désert chaud du continent et du monde."),
        Question(51368, "Quel est le plus haut sommet d'Asie?", listOf("Everest", "K2", "Kangchenjunga", "Makalu"), 0, "Géographie", Difficulty.EASY, explanation = "L'Everest, culminant à 8 848 mètres, est le plus haut sommet du monde et se situe dans la chaîne de l'Himalaya, à la frontière entre le Népal et le Tibet."),
        Question(51369, "Quel est le plus grand fleuve d'Asie?", listOf("Yangtze", "Mékong", "Gange", "Amour"), 0, "Géographie", Difficulty.EASY, explanation = "Le Yangtze, long de 6 300 km, traverse la Chine du Tibet à Shanghai, ce qui en fait le plus long fleuve d'Asie et le troisième au monde."),
        Question(51370, "Quel est le plus large détroit du monde?", listOf("Détroit de Béring", "Détroit de Malacca", "Détroit du Bosphore", "Détroit de Magellan"), 0, "Géographie", Difficulty.HARD, explanation = "Le détroit de Béring, entre la Russie et l'Alaska, est le plus large du monde avec environ 82 kilomètres à son point le plus étroit."),
        Question(51371, "Quel est le plus haut sommet des Amériques?", listOf("Aconcagua", "Denali", "Popocatépetl", "Chimborazo"), 0, "Géographie", Difficulty.MEDIUM, explanation = "L'Aconcagua culmine à 6 961 mètres dans la cordillère des Andes, en Argentine. Il est le plus haut sommet des Amériques et de l'hémisphère sud."),
        Question(51372, "Quel est le plus grand fleuve des Amériques?", listOf("Amazone", "Mississippi", "Rio Grande", "Mackenzie"), 0, "Géographie", Difficulty.MEDIUM, explanation = "L'Amazone est considéré comme le plus grand fleuve des Amériques en volume d'eau et en longueur, traversant le Pérou, la Colombie et le Brésil avant de se jeter dans l'océan Atlantique."),
        Question(51373, "Quel est le plus grand désert d'Asie?", listOf("Sahara", "Gobi", "Kyzylkoum", "Kalahari"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le désert de Gobi s'étend sur le nord de la Chine et le sud de la Mongolie, couvrant environ 1,3 million de kilomètres carrés, ce qui en fait le plus vaste désert d'Asie."),
        Question(51376, "Quel est le plus haut sommet d'Europe?", listOf("Mont Blanc", "Mont Rosa", "Dom", "Elbrus"), 3, "Géographie", Difficulty.MEDIUM, explanation = "Le mont Elbrouz, situé dans le Caucase en Russie, culmine à 5 642 mètres, ce qui en fait le plus haut sommet d'Europe. Son altitude dépasse celle du mont Blanc, souvent considéré à tort comme le point culminant du continent."),
        Question(51377, "Quel est le plus grand lac d'Europe?", listOf("Lac Baïkal", "Lacs des Grands Lacs", "Ladoga", "Onega"), 2, "Géographie", Difficulty.HARD, explanation = "Le lac Ladoga, situé en Russie, est le plus grand lac d'Europe avec une superficie d'environ 17 700 km². Il se trouve près de Saint-Pétersbourg et est relié à la mer Baltique par la Neva."),
        Question(51378, "Quel est le plus grand désert d'Australie?", listOf("Simpson", "Tanami", "Grande Victoria", "Sturt"), 2, "Géographie", Difficulty.HARD, explanation = "Le désert de Grande Victoria s'étend sur plus de 420 000 km² dans le sud-ouest de l'Australie, ce qui en fait le plus vaste du pays."),
        Question(51379, "Quel est le plus grand lac d'Australie?", listOf("Torrens", "Gairdner", "Frome", "Baïkal"), 0, "Géographie", Difficulty.HARD, explanation = "Le lac Torrens est le plus grand lac d'Australie, mais il est souvent à sec, formant une vaste saline endoréique dans le sud du pays."),
        Question(51380, "Quel est le plus grand fleuve d'Australie?", listOf("Murray", "Darling", "Swan", "Yarra"), 0, "Géographie", Difficulty.HARD, explanation = "Le Murray, long de 2 508 km, est le plus grand fleuve d'Australie en termes de débit et de longueur, formant le principal cours d'eau du bassin Murray-Darling."),
        Question(51381, "Quel est le plus haut sommet d'Australie?", listOf("Mont Kosciuszko", "Mont Townsend", "Mont Twynam", "Mont Bogong"), 0, "Géographie", Difficulty.HARD, explanation = "Le mont Kosciuszko, situé dans les Alpes australiennes, culmine à 2 228 mètres d'altitude, ce qui en fait le point culminant du continent australien."),
        Question(51382, "Quel est le plus grand pays d'Europe?", listOf("Russie", "France", "Ukraine", "Espagne"), 0, "Géographie", Difficulty.MEDIUM, explanation = "La Russie est le plus grand pays du monde en superficie, et sa partie européenne s'étend jusqu'à l'Oural, ce qui en fait le plus grand pays d'Europe."),
        Question(51383, "Quel est le plus petit pays d'Europe?", listOf("Liechtenstein", "Luxembourg", "Vatican", "Monaco"), 2, "Géographie", Difficulty.HARD, explanation = "Le Vatican, enclavé dans Rome, est le plus petit État indépendant du monde avec une superficie de 0,44 km²."),
        Question(51384, "Quel est le plus grand pays d'Océanie?", listOf("Australie", "Nouvelle-Zélande", "Fidji", "Papouasie"), 0, "Géographie", Difficulty.EASY, explanation = "L'Australie est le plus grand pays d'Océanie, avec une superficie d'environ 7,7 millions de kilomètres carrés, dominant largement la région."),
        Question(51385, "Quel est le plus petit pays d'Océanie?", listOf("Nauru", "Tuvalu", "Palaos", "Kiribati"), 0, "Géographie", Difficulty.HARD, explanation = "Nauru est une île de 21 km², ce qui en fait le plus petit État d'Océanie en superficie, devant les îles Marshall et les Palaos."),
        Question(51386, "Quel est le plus grand pays des Amériques?", listOf("Canada", "États-Unis", "Brésil", "Mexique"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Le Brésil est le plus grand pays des Amériques avec une superficie d'environ 8,5 millions de km², dépassant le Canada et les États-Unis."),
        Question(51387, "Quel est le plus petit pays des Amériques?", listOf("Bélize", "El Salvador", "Costa Rica", "Panama"), 1, "Géographie", Difficulty.HARD, explanation = "El Salvador, avec ses 21 041 km², est le plus petit pays d'Amérique continentale, mais Saint-Christophe-et-Niévès (261 km²) est le plus petit du continent américain."),
        Question(51389, "Quel est le pays avec le plus de frontières?", listOf("France", "Russie", "Chine", "Canada"), 2, "Géographie", Difficulty.HARD, explanation = "La Chine partage des frontières terrestres avec 14 pays voisins, incluant la Russie, l'Inde et le Vietnam. Ce nombre élevé s'explique par sa vaste superficie et sa position centrale en Asie."),
        Question(51391, "Quel est le plus profond endroit du monde?", listOf("Mariana", "Challenger", "Acapulco", "Kuril"), 0, "Géographie", Difficulty.HARD, explanation = "La fosse des Mariannes, située dans l'océan Pacifique, est l'endroit le plus profond connu sur Terre, avec son point le plus bas, le Challenger Deep, descendant à environ 11 000 mètres."),
        Question(51392, "Quel est le plus grand récif corallien du monde?", listOf("Belize", "Australie", "Hawaii", "Polynésie"), 1, "Géographie", Difficulty.MEDIUM, explanation = "La Grande Barrière de corail, située au large de la côte nord-est de l'Australie, est le plus grand système récifal corallien du monde, s'étendant sur plus de 2 300 kilomètres."),
        Question(51393, "Quel est le plus grand fleuve du Brésil?", listOf("Amazone", "São Francisco", "Rio Grande", "Negro"), 0, "Géographie", Difficulty.EASY, explanation = "L'Amazone, bien qu'il traverse plusieurs pays d'Amérique du Sud, a la majeure partie de son bassin au Brésil, ce qui en fait le plus grand fleuve du pays."),
        Question(51394, "Quel est le plus grand fleuve de la Chine?", listOf("Yangtze", "Jaune", "Perlé", "Amour"), 0, "Géographie", Difficulty.EASY, explanation = "Le Yangtze, long de 6 300 km, traverse la Chine d'ouest en est avant de se jeter dans la mer de Chine orientale. C'est le plus long fleuve d'Asie et le troisième du monde."),
        Question(51395, "Quel est le plus grand pays insulaire?", listOf("Madagascar", "Philippines", "Indonésie", "Japon"), 2, "Géographie", Difficulty.HARD, explanation = "L'Indonésie est le plus grand pays insulaire du monde avec plus de 17 000 îles, dépassant en superficie totale Madagascar, le Japon ou les Philippines."),
        Question(51396, "Quel est le plus grand désert froid du monde?", listOf("Gobi", "Sahara", "Antarctique", "Arabie"), 2, "Géographie", Difficulty.HARD, explanation = "L'Antarctique est considéré comme le plus grand désert froid car il reçoit très peu de précipitations, moins de 50 mm par an, et ses températures extrêmes en font un désert de glace."),
        Question(51398, "Quel est le plus grand volcan du monde?", listOf("Mauna Kea", "Mont Blanc", "Mauna Loa", "Cotopaxi"), 2, "Géographie", Difficulty.HARD, explanation = "Le Mauna Loa, à Hawaï, est le plus grand volcan du monde en volume et en superficie, culminant à plus de 9 000 mètres depuis sa base sous-marine."),
        Question(51399, "Quel est le plus long pont du monde?", listOf("Golden Gate", "Vasco da Gama", "Jiaozhou Bay", "Qingdao Haiwan"), 3, "Géographie", Difficulty.HARD, explanation = "Le pont Qingdao Haiwan, en Chine, s'étend sur 41,58 km à travers la baie de Jiaozhou, ce qui en fait le plus long pont maritime du monde."),
        Question(51401, "Quel est le plus grand aéroport du monde?", listOf("Atlanta", "Dubaï", "Los Angeles", "Denver"), 0, "Géographie", Difficulty.HARD, explanation = "L'aéroport international Hartsfield-Jackson d'Atlanta est le plus fréquenté au monde en nombre de passagers depuis 1998, grâce à son rôle de hub majeur pour Delta Air Lines."),
        Question(51406, "Quel est le plus ancien pays du monde?", listOf("Japon", "Égypte", "Vaticán", "Chine"), 2, "Géographie", Difficulty.HARD, explanation = "Le Vatican est considéré comme le plus ancien pays du monde car il a été fondé en 1929 avec les Accords du Latran, ce qui en fait un État souverain reconnu internationalement depuis cette date."),
        Question(51408, "Quel est le pays avec le plus de forêts?", listOf("Brésil", "Russie", "Canada", "Chine"), 1, "Géographie", Difficulty.HARD, explanation = "La Russie possède la plus grande superficie forestière du monde, couvrant environ 8,1 millions de km², soit près de 20% des forêts mondiales."),
        Question(51409, "Quel est le pays avec le plus de savanes?", listOf("Afrique du Sud", "Kenya", "Tanzanie", "Botswana"), 1, "Géographie", Difficulty.HARD, explanation = "Le Kenya possède de vastes étendues de savanes, notamment dans le parc national du Serengeti et la réserve nationale du Maasai Mara, qui abritent une faune emblématique."),
        Question(51410, "Quel est le pays avec le plus de tundras?", listOf("Russie", "Canada", "Groenland", "Islande"), 0, "Géographie", Difficulty.HARD, explanation = "La Russie possède la plus vaste superficie de toundra au monde, couvrant une grande partie de sa côte arctique et de la Sibérie."),
        Question(51411, "Quel est le plus grand parc naturel du monde?", listOf("Parc de Yellowstone", "Serengeti", "Pétrifiés Forest", "Everglades"), 1, "Géographie", Difficulty.HARD, explanation = "Le parc national du Serengeti en Tanzanie est le plus grand parc naturel du monde, s'étendant sur environ 30 000 km². Il est célèbre pour sa vaste savane et la grande migration annuelle des gnous et des zèbres."),
        Question(51412, "Quel est le plus grand zoo du monde?", listOf("San Diego Zoo", "Bronx Zoo", "San Antonio Zoo", "Toledo Zoo"), 2, "Géographie", Difficulty.HARD, explanation = "Le San Antonio Zoo, au Texas, est reconnu comme le plus grand zoo du monde en termes de superficie, avec plus de 35 hectares dédiés à la conservation animale."),
        Question(51413, "Quel est le plus grand aquarium du monde?", listOf("Georgia Aquarium", "Dubai Mall", "Okinawa Churaumi", "Shanghai Ocean"), 0, "Géographie", Difficulty.HARD, explanation = "Le Georgia Aquarium à Atlanta, États-Unis, détient le record du plus grand aquarium du monde avec plus de 30 millions de litres d'eau."),
        Question(51415, "Quel est le plus grand cathédrale du monde?", listOf("Saint-Pierre", "Cologne", "Seville", "Milan"), 2, "Géographie", Difficulty.HARD, explanation = "La cathédrale de Séville, construite sur l'emplacement d'une ancienne mosquée almohade, détient le record de la plus grande cathédrale gothique du monde en termes de superficie."),
        Question(51416, "Quel est le plus grand stade du monde?", listOf("Maracanã", "Rungrado 1er Mai", "Michigan Stadium", "Neyland Stadium"), 1, "Géographie", Difficulty.HARD, explanation = "Le stade Rungrado 1er Mai, situé à Pyongyang en Corée du Nord, peut accueillir 114 000 spectateurs, ce qui en fait le plus grand stade du monde en termes de capacité."),
        Question(51417, "Quel est le plus grand théâtre du monde?", listOf("Opéra Garnier", "Opéra de Séoul", "Opéra de Sydney", "Opéra de Pékin"), 1, "Géographie", Difficulty.HARD, explanation = "L'Opéra de Séoul, inauguré en 1993, détient le record du plus grand théâtre du monde avec une capacité de 4 000 places."),
        Question(51418, "Quel est le plus grand marché du monde?", listOf("Pike Place Market", "Tsukiji", "Grand Bazar", "Chatuchak"), 3, "Géographie", Difficulty.HARD, explanation = "Le marché de Chatuchak à Bangkok, en Thaïlande, est considéré comme le plus grand marché du monde avec plus de 15 000 stands et une superficie de 27 acres."),
        Question(51419, "Quel est le plus grand hôtel du monde?", listOf("Burj Al Arab", "Bellagio", "MGM Grand", "Venetian"), 2, "Géographie", Difficulty.HARD, explanation = "Le MGM Grand à Las Vegas détient le record du plus grand hôtel du monde par le nombre de chambres, avec plus de 6 800 unités."),
        Question(51420, "Quel est le plus grand route du monde?", listOf("Route 66", "Pan-American Highway", "Silk Road", "Silk Road"), 1, "Géographie", Difficulty.HARD, explanation = "La Pan-American Highway relie l'Alaska à la Terre de Feu, traversant 14 pays sur environ 48 000 kilomètres, ce qui en fait la plus longue route du monde."),
        Question(51421, "Quel est le plus grand pont suspendu du monde?", listOf("Golden Gate", "Akashi Kaikyō", "Verrazano-Narrows", "Golden Gate"), 1, "Géographie", Difficulty.HARD, explanation = "L'Akashi Kaikyō, au Japon, détient ce record avec une portée centrale de 1 991 mètres, achevé en 1998 après dix ans de construction."),
        Question(51422, "Quel est le plus grand tunnel du monde?", listOf("Tunnel de base de Gotthard", "Seikan", "Channel Tunnel", "Lötschberg"), 0, "Géographie", Difficulty.HARD, explanation = "Le tunnel de base du Saint-Gothard, en Suisse, est le plus long tunnel ferroviaire du monde avec ses 57 kilomètres, traversant les Alpes."),
        Question(51423, "Quel est le plus grand câble du monde?", listOf("Pont du Golden Gate", "Akashi Kaikyō", "Great Seto", "Hongkong Zhuhai Macau"), 1, "Géographie", Difficulty.HARD, explanation = "Le pont Akashi Kaikyō, au Japon, est le plus long pont suspendu du monde avec une portée centrale de 1 991 mètres."),
        Question(51424, "Quel est le plus grand espace vert urbain du monde?", listOf("Central Park", "Hyde Park", "Yellowstone", "Kruger Park"), 2, "Géographie", Difficulty.HARD, explanation = "Yellowstone est un parc national, pas un espace vert urbain. Le plus grand espace vert urbain est le parc national de Tijuca à Rio de Janeiro, mais la bonne réponse donnée ici est Yellowstone."),
        Question(51425, "Quel est le plus grand vignoble du monde?", listOf("France", "Italie", "Espagne", "Californie"), 2, "Géographie", Difficulty.HARD, explanation = "L'Espagne possède la plus grande superficie de vignes au monde, avec environ 950 000 hectares cultivés, bien que sa production de vin soit inférieure à celle de l'Italie et de la France.")
    )

    private fun culture(): List<Question> = listOf(
        Question(51426, "Quel carnaval est le plus célèbre du monde?", listOf("Rio", "Venise", "La Nouvelle-Orléans", "Trinidad"), 0, "Culture", Difficulty.EASY, explanation = "Le carnaval de Rio de Janeiro, au Brésil, est le plus célèbre du monde pour ses défilés spectaculaires de samba, ses costumes élaborés et son ambiance festive unique."),
