        Question(51428, "Quel danse traditionnelle est originaire d'Irlande?", listOf("Flamenco", "Riverdance", "Tango", "Samba"), 1, "Culture", Difficulty.EASY, explanation = "Riverdance est un spectacle de danse irlandaise créé en 1994, popularisé mondialement par son mélange de danse traditionnelle et de musique celtique."),
        Question(51429, "Quel danse traditionnelle est originaire d'Espagne?", listOf("Flamenco", "Riverdance", "Tango", "Samba"), 0, "Culture", Difficulty.EASY, explanation = "Le flamenco est un art andalou mêlant chant, guitare, danse et percussions, né au 18e siècle dans le sud de l'Espagne. Il est reconnu comme patrimoine culturel immatériel de l'humanité par l'UNESCO."),
        Question(51430, "Quel danse traditionnelle est originaire d'Argentine?", listOf("Flamenco", "Riverdance", "Tango", "Samba"), 2, "Culture", Difficulty.EASY, explanation = "Le tango est né dans les quartiers populaires de Buenos Aires à la fin du XIXe siècle, mêlant influences africaines, européennes et locales."),
        Question(51431, "Quel danse traditionnelle est originaire du Brésil?", listOf("Flamenco", "Riverdance", "Tango", "Samba"), 3, "Culture", Difficulty.EASY, explanation = "La samba est une danse et un genre musical nés à Rio de Janeiro, fortement influencés par les rythmes africains apportés par les esclaves."),
        Question(51432, "Quel religion a le plus de fidèles au monde?", listOf("Islam", "Christianisme", "Hindouisme", "Bouddhisme"), 1, "Culture", Difficulty.EASY, explanation = "Le christianisme est la religion comptant le plus de fidèles dans le monde, avec environ 2,4 milliards de croyants, suivie par l'islam."),
        Question(51433, "Quel religion est la plus vieille du monde?", listOf("Hindouisme", "Zoroastrisme", "Bouddhisme", "Taoïsme"), 0, "Culture", Difficulty.MEDIUM, explanation = "L'hindouisme est considéré comme la plus ancienne religion majeure encore pratiquée, ses racines remontant à plus de 4000 ans dans la vallée de l'Indus."),
        Question(51434, "Quel site UNESCO est le plus visité?", listOf("Taj Mahal", "Machu Picchu", "Angkor Wat", "Chichen Itza"), 0, "Culture", Difficulty.HARD, explanation = "Le Taj Mahal, mausolée emblématique de l'Inde, attire plus de visiteurs annuels que tout autre site classé au patrimoine mondial de l'UNESCO."),
        Question(51435, "Quel site UNESCO est le plus grand?", listOf("Taj Mahal", "Machu Picchu", "Angkor Wat", "Chichen Itza"), 2, "Culture", Difficulty.HARD, explanation = "Angkor Wat, au Cambodge, est le plus grand site UNESCO avec une superficie de 401 km², dépassant largement d'autres sites comme le parc national de Yellowstone."),
        Question(51436, "Quel site UNESCO est le plus ancien?", listOf("Taj Mahal", "Machu Picchu", "Giza", "Persépolis"), 2, "Culture", Difficulty.HARD, explanation = "Le site de Gizeh, avec ses pyramides et le Sphinx, a été inscrit au patrimoine mondial de l'UNESCO en 1979, mais il est considéré comme le plus ancien site inscrit en raison de son âge et de son importance historique."),
        Question(51437, "Quel culture indigène est la plus grande?", listOf("Mayas", "Aztèques", "Incas", "Aucun"), 3, "Culture", Difficulty.HARD, explanation = "La notion de \"plus grande culture indigène\" est subjective et varie selon les critères (population, territoire, influence). Aucune culture ne peut être objectivement désignée comme la plus grande."),
        Question(51438, "Quel festival internet est le plus populaire?", listOf("Meme festival", "Forum festival", "Reddit festival", "TikTok festival"), 3, "Culture", Difficulty.HARD, explanation = "Le TikTok Festival, lancé en 2020, rassemble des créateurs et des millions de spectateurs en ligne, devenant un événement majeur de la culture numérique."),
        Question(51439, "Quel mème internet est le plus célèbre?", listOf("Rickroll", "Harambe", "Loss", "Distracted Boyfriend"), 0, "Culture", Difficulty.MEDIUM, explanation = "Le Rickroll est un mème où un lien prétendant mener à un contenu intéressant redirige vers le clip de Rick Astley \"Never Gonna Give You Up\". Il est devenu viral en 2007 et reste l'un des mèmes les plus durables et reconnus."),
        Question(51440, "Quel est le mème internet le plus ancien?", listOf("All Your Base", "LOLcats", "Rickroll", "Numa Numa"), 0, "Culture", Difficulty.HARD, explanation = "Le mème \"All Your Base Are Belong To Us\" provient d'une traduction approximative du jeu vidéo Zero Wing (1989) et a été popularisé sur internet au début des années 2000."),
        Question(51441, "Quel carnaval est le plus grand du monde?", listOf("Rio", "Venise", "La Nouvelle-Orléans", "Trinidad"), 0, "Culture", Difficulty.EASY, explanation = "Le carnaval de Rio de Janeiro est reconnu comme le plus grand du monde en raison de son nombre de participants, de ses défilés spectaculaires et de sa renommée internationale."),
        Question(51442, "Quel carnaval a lieu au printemps?", listOf("Rio", "Venise", "La Nouvelle-Orléans", "Carême"), 1, "Culture", Difficulty.MEDIUM, explanation = "Le Carnaval de Venise se déroule généralement en février ou mars, avant le Carême, ce qui le place au printemps."),
        Question(51443, "Quel danse traditionnelle est la plus complexe?", listOf("Flamenco", "Ballet", "Kathak", "Kathakali"), 2, "Culture", Difficulty.HARD, explanation = "Le kathak est considéré comme l'une des danses les plus complexes en raison de ses jeux de pieds rapides, ses rotations précises et ses expressions faciales nuancées, nécessitant des années de pratique."),
        Question(51444, "Quel danse traditionnelle est la plus ancienne?", listOf("Tango", "Ballet", "Kathakali", "Flamenco"), 2, "Culture", Difficulty.HARD, explanation = "Le Kathakali est une danse traditionnelle indienne originaire du Kerala, dont les origines remontent au 17e siècle, ce qui en fait l'une des formes de danse les plus anciennes encore pratiquées."),
        Question(51445, "Quel religion a le plus de temples?", listOf("Hindouisme", "Bouddhisme", "Christianisme", "Islam"), 0, "Culture", Difficulty.HARD, explanation = "L'Inde compte plus d'un million de temples hindous, bien plus que toute autre religion, en raison de la diversité des divinités et des pratiques locales."),
        Question(51446, "Quel religion a le moins de fidèles?", listOf("Zoroastrisme", "Jaïnisme", "Shintoïsme", "Taoïsme"), 1, "Culture", Difficulty.HARD, explanation = "Le jaïnisme compte environ 4 à 5 millions de fidèles dans le monde, principalement en Inde, ce qui en fait l'une des religions majeures les moins pratiquées."),
        Question(51447, "Quel site UNESCO a été le plus dégradé?", listOf("Taj Mahal", "Bamiyan", "Angkor Wat", "Knossos"), 1, "Culture", Difficulty.HARD, explanation = "Les Bouddhas de Bamiyan en Afghanistan ont été dynamités par les talibans en 2001, ce qui a conduit à leur destruction quasi totale et à leur inscription sur la liste du patrimoine en péril de l'UNESCO."),
        Question(51448, "Quel site UNESCO est le plus récent?", listOf("Taj Mahal", "Machu Picchu", "Mont Saint-Michel", "2023 additions"), 3, "Culture", Difficulty.HARD, explanation = "Les sites ajoutés en 2023, comme les forêts sacrées de Kayah au Myanmar ou les sites de la culture Jōmon au Japon, sont les plus récents inscrits au patrimoine mondial de l'UNESCO."),
        Question(51449, "Quel culture indigène a l'écriture la plus ancienne?", listOf("Mayas", "Égyptiens", "Sumériens", "Minoens"), 2, "Culture", Difficulty.HARD, explanation = "L'écriture cunéiforme sumérienne, apparue vers 3400 av. J.-C. en Mésopotamie, est considérée comme le plus ancien système d'écriture connu."),
        Question(51450, "Quel festival internet a le plus de participants?", listOf("Twitch Plays", "Reddit Place", "Bitcoin Festival", "Decentraland"), 1, "Culture", Difficulty.HARD, explanation = "Reddit Place est un événement collaboratif où des millions d'utilisateurs placent des pixels sur une toile virtuelle, atteignant des records de participation."),
        Question(51451, "Quel est le mème internet le plus viral?", listOf("Doge", "Harambe", "Fidget Spinner", "Among Us"), 0, "Culture", Difficulty.HARD, explanation = "Le mème Doge, représentant un Shiba Inu avec des pensées en Comic Sans, est devenu viral à partir de 2013 sur des plateformes comme Reddit et Tumblr, symbolisant l'humour absurde d'internet."),
        Question(51452, "Quel est le mème internet le plus durable?", listOf("Rickroll", "Lolcats", "Distracted Boyfriend", "Loss"), 0, "Culture", Difficulty.HARD, explanation = "Le Rickroll est un mème basé sur le clip du tube \"Never Gonna Give You Up\" de Rick Astley (1987), utilisé comme canular pour rediriger des internautes vers cette vidéo depuis 2007. Sa longévité tient à sa simplicité et à sa capacité à surprendre encore aujourd'hui."),
        Question(51453, "Quel carnaval est le plus coloré?", listOf("Rio", "Venise", "La Nouvelle-Orléans", "Trinidad"), 0, "Culture", Difficulty.MEDIUM, explanation = "Le carnaval de Rio de Janeiro est mondialement reconnu pour ses défilés spectaculaires aux costumes éclatants et ses chars richement décorés."),
        Question(51454, "Quel carnaval dure le plus longtemps?", listOf("Rio", "Venise", "La Nouvelle-Orléans", "Trinidad"), 2, "Culture", Difficulty.HARD, explanation = "Le carnaval de La Nouvelle-Orléans, connu sous le nom de Mardi Gras, s'étend officiellement de l'Épiphanie (6 janvier) au Mardi Gras, soit environ deux mois."),
        Question(51455, "Quel danse traditionnelle est la plus gracieuse?", listOf("Ballet", "Flamenco", "Tango", "Valse"), 0, "Culture", Difficulty.MEDIUM, explanation = "Le ballet est considéré comme la danse la plus gracieuse en raison de sa technique rigoureuse, de ses mouvements fluides et de son esthétique visuelle, développée à la cour de France au XVIIe siècle."),
        Question(51456, "Quel danse traditionnelle est la plus passionnée?", listOf("Flamenco", "Ballet", "Valse", "Pouloulkous"), 0, "Culture", Difficulty.MEDIUM, explanation = "Le flamenco, originaire d'Andalousie, est reconnu pour son intensité émotionnelle, mêlant chant, guitare et danse expressive."),
        Question(51457, "Quel religion est la plus pratiquée en Asie?", listOf("Bouddhisme", "Hindouisme", "Taoïsme", "Confucianisme"), 1, "Culture", Difficulty.HARD, explanation = "L'hindouisme est la religion majoritaire en Inde et au Népal, et compte plus d'un milliard de fidèles, principalement concentrés en Asie du Sud."),
        Question(51458, "Quel religion est la plus pratiquée en Afrique?", listOf("Christianisme", "Islam", "Animisme", "Hindouisme"), 0, "Culture", Difficulty.MEDIUM, explanation = "Le christianisme est la religion la plus pratiquée en Afrique, suivi de près par l'islam, en raison de l'histoire coloniale et des missions chrétiennes."),
        Question(51459, "Quel site UNESCO a le plus de visiteurs?", listOf("Taj Mahal", "Statue de la Liberté", "Big Ben", "Colosseum"), 3, "Culture", Difficulty.HARD, explanation = "Le Colisée de Rome est le site classé à l'UNESCO le plus visité au monde, attirant environ 7,6 millions de touristes par an."),
        Question(51460, "Quel site UNESCO est le plus menacé?", listOf("Bamiyan", "Venice", "Galapagos", "Serengeti"), 0, "Culture", Difficulty.HARD, explanation = "Les statues de Bouddha de Bamiyan, en Afghanistan, ont été classées au patrimoine mondial en péril après leur destruction par les talibans en 2001."),
        Question(51461, "Quel culture indigène a la plus longue histoire?", listOf("Mayas", "Aztèques", "Incas", "Égyptiens"), 3, "Culture", Difficulty.HARD, explanation = "La civilisation égyptienne antique est l'une des plus anciennes, avec des traces d'occupation humaine remontant à environ 3100 avant J.-C., ce qui en fait la culture indigène continue la plus longue."),
        Question(51462, "Quel festival internet a le plus d'influence?", listOf("Twitch Plays", "Reddit Place", "Bitcoin Festival", "Decentraland"), 0, "Culture", Difficulty.HARD, explanation = "Twitch Plays a démontré une influence massive en permettant à des milliers de spectateurs de contrôler collectivement un jeu vidéo en temps réel, créant un phénomène viral et une nouvelle forme de divertissement participatif."),
        Question(51463, "Quel est le mème internet le plus imitable?", listOf("Rickroll", "Doge", "Nyan Cat", "Distracted Boyfriend"), 2, "Culture", Difficulty.HARD, explanation = "Nyan Cat est un mème devenu viral en 2011 grâce à son animation simple d'un chat volant avec un corps de pop-tart, accompagnée d'une musique entraînante, ce qui l'a rendu facile à reproduire et à imiter."),
        Question(51464, "Quel est le mème internet le plus diversifié?", listOf("Rickroll", "Lolcats", "Distracted Boyfriend", "Impact"), 3, "Culture", Difficulty.HARD, explanation = "Le mème \"Impact\" est devenu l'un des plus diversifiés car il se décline en une multitude de variations, allant de l'impact visuel à l'impact émotionnel, souvent utilisé pour commenter des situations inattendues ou marquantes."),
        Question(51465, "Quel carnaval a la plus grande parade?", listOf("Rio", "Venise", "La Nouvelle-Orléans", "Trinidad"), 0, "Culture", Difficulty.HARD, explanation = "Le Carnaval de Rio de Janeiro est inscrit au Guinness World Records comme le plus grand carnaval du monde, avec des défilés spectaculaires de samba rassemblant des millions de participants et spectateurs."),
        Question(51466, "Quel carnaval est le plus traditionnel?", listOf("Rio", "Venise", "La Nouvelle-Orléans", "Trinidad"), 1, "Culture", Difficulty.HARD, explanation = "Le Carnaval de Venise, avec ses masques et costumes historiques, remonte au XIIIe siècle et est considéré comme l'un des plus anciens et authentiques."),
        Question(51467, "Quel danse traditionnelle a la meilleure musique?", listOf("Flamenco", "Ballet", "Tango", "Opéra"), 2, "Culture", Difficulty.HARD, explanation = "Le tango, né dans les quartiers populaires de Buenos Aires et Montevideo, est reconnu pour sa musique passionnée mêlant bandonéon, violon et piano, classée au patrimoine immatériel de l'UNESCO."),
        Question(51468, "Quel danse traditionnelle a les costumes les plus élaborés?", listOf("Flamenco", "Kathakali", "Ballet", "Opéra"), 1, "Culture", Difficulty.HARD, explanation = "Le Kathakali est un art dramatique dansé du Kerala, en Inde, dont les costumes et maquillages très codifiés et colorés sont extrêmement élaborés, chaque couleur représentant un trait de caractère spécifique."),
        Question(51469, "Quel religion a le plus de diversité?", listOf("Bouddhisme", "Christianisme", "Islam", "Hindouisme"), 1, "Culture", Difficulty.HARD, explanation = "Le christianisme est la religion la plus diversifiée au monde, avec des branches principales comme le catholicisme, le protestantisme et l'orthodoxie, ainsi que des milliers de dénominations locales."),
        Question(51470, "Quel religion a le moins de temples?", listOf("Zoroastrisme", "Jaïnisme", "Shintoïsme", "Taoïsme"), 0, "Culture", Difficulty.HARD, explanation = "Le zoroastrisme compte très peu de temples car ses pratiquants sont peu nombreux, environ 100 000 dans le monde, principalement en Inde et en Iran."),
        Question(51471, "Quel site UNESCO a le meilleur architecture?", listOf("Taj Mahal", "Versailles", "Colosseum", "Sagrada Familia"), 3, "Culture", Difficulty.HARD, explanation = "La Sagrada Familia à Barcelone, conçue par Antoni Gaudí, est un site UNESCO depuis 2005 pour son architecture moderniste unique et son importance culturelle."),
        Question(51472, "Quel site UNESCO a la meilleure histoire?", listOf("Taj Mahal", "Angkor Wat", "Knossos", "Persépolis"), 1, "Culture", Difficulty.HARD, explanation = "Angkor Wat, au Cambodge, est le plus grand monument religieux du monde et un chef-d'œuvre de l'architecture khmère, classé à l'UNESCO en 1992."),
        Question(51473, "Quel culture indigène a le plus d'influence?", listOf("Mayas", "Aztèques", "Incas", "Amérindiens"), 3, "Culture", Difficulty.HARD, explanation = "Les Amérindiens ont profondément marqué l'histoire et la culture des Amériques, avec des contributions durables dans l'agriculture, la langue et les traditions."),
        Question(51474, "Quel festival internet a le plus de durée?", listOf("Twitch Plays", "Reddit Place", "Bitcoin Festival", "Metaverse"), 3, "Culture", Difficulty.HARD, explanation = "Le Metaverse est un concept d'univers virtuel persistant et interconnecté, accessible en continu, contrairement à un événement limité dans le temps comme un festival traditionnel."),
        Question(51475, "Quel est le mème internet le plus crossover?", listOf("Rickroll", "Doge", "Thanos", "Infinity Stones"), 3, "Culture", Difficulty.HARD, explanation = "Le mème \"Infinity Stones\" vient de l'univers Marvel, où ces pierres sont des artefacts cosmiques. Il est devenu un mème crossover car il est utilisé pour parodier n'importe quelle collection d'objets dans divers fandoms."),
        Question(51476, "Quel est le mème internet le plus influent?", listOf("Rickroll", "Doge", "Harambe", "Distracted Boyfriend"), 1, "Culture", Difficulty.HARD, explanation = "Le mème Doge, avec son chien Shiba Inu et son texte en Comic Sans, est devenu emblématique de la culture internet des années 2010, influençant même la cryptomonnaie du même nom."),
        Question(51477, "Quel carnaval a la meilleure ambiance?", listOf("Rio", "Venise", "La Nouvelle-Orléans", "Trinidad"), 3, "Culture", Difficulty.HARD, explanation = "Le Carnaval de Trinidad est mondialement reconnu pour son ambiance électrique, ses défilés colorés et sa musique entraînante, notamment le calypso et le soca."),
        Question(51478, "Quel carnaval est le plus cher?", listOf("Rio", "Venise", "La Nouvelle-Orléans", "Trinidad"), 0, "Culture", Difficulty.HARD, explanation = "Le Carnaval de Rio est le plus cher en raison de ses défilés spectaculaires, avec des écoles de samba aux costumes élaborés et chars monumentaux, nécessitant des budgets de plusieurs millions de dollars."),
        Question(51479, "Quel danse traditionnelle est la plus difficile à apprendre?", listOf("Ballet", "Flamenco", "Tango", "Opéra"), 0, "Culture", Difficulty.HARD, explanation = "Le ballet exige des années de pratique intensive pour maîtriser la technique, la souplesse et la précision des mouvements, ce qui en fait l'une des danses les plus exigeantes physiquement et techniquement."),
        Question(51480, "Quel danse traditionnelle est la plus rapide?", listOf("Flamenco", "Ballet", "Tango", "Valse"), 0, "Culture", Difficulty.HARD, explanation = "Le flamenco, originaire d'Andalousie, est connu pour ses rythmes vifs et ses mouvements rapides des pieds, ce qui en fait l'une des danses traditionnelles les plus rapides."),
        Question(51481, "Quel religion a le plus de différentes écoles?", listOf("Bouddhisme", "Christianisme", "Islam", "Hindouisme"), 3, "Culture", Difficulty.HARD, explanation = "L'hindouisme ne possède pas de dogme central ni d'autorité unique, ce qui a permis l'émergence de nombreuses écoles philosophiques et traditions, comme le Vedanta, le Yoga ou le Shivaïsme."),
        Question(51482, "Quel religion est la plus jeune?", listOf("Mormonisme", "Babisme", "Bahaïsme", "Scientologie"), 2, "Culture", Difficulty.HARD, explanation = "Le bahaïsme est la plus jeune des grandes religions, fondée au XIXe siècle en Perse par Baha'u'llah, soit bien après l'islam ou le christianisme."),
        Question(51483, "Quel site UNESCO a le plus d'importance historique?", listOf("Taj Mahal", "Angkor Wat", "Versailles", "Knossos"), 3, "Culture", Difficulty.HARD, explanation = "Knossos est le plus important site archéologique de l'âge du bronze en Crète, associé à la civilisation minoenne et au mythe du Labyrinthe du roi Minos."),
        Question(51484, "Quel site UNESCO est le plus unique?", listOf("Taj Mahal", "Galapagos", "Machu Picchu", "Stonehenge"), 1, "Culture", Difficulty.HARD, explanation = "Les îles Galápagos sont un site UNESCO unique car leur isolement a permis l'évolution d'espèces endémiques, comme les tortues géantes et les iguanes marins, qui ont inspiré la théorie de l'évolution de Darwin."),
        Question(51485, "Quel culture indigène a la plus grande population actuelle?", listOf("Mayas", "Aztèques", "Incas", "Amérindiens"), 3, "Culture", Difficulty.HARD, explanation = "Les Amérindiens regroupent de nombreux peuples autochtones des Amériques, et leur population totale estimée à plus de 60 millions de personnes en fait la culture indigène la plus nombreuse aujourd'hui."),
        Question(51486, "Quel festival internet a le plus grand impact sociétal?", listOf("Twitch Plays", "Reddit Place", "April Fools", "Metaverse"), 2, "Culture", Difficulty.HARD, explanation = "Le April Fools Day, ou Poisson d'Avril, est un événement mondial où les internautes et grandes entreprises créent des canulars, influençant massivement les tendances et discussions en ligne."),
        Question(51487, "Quel est le mème internet le plus politique?", listOf("Rickroll", "Doge", "Political Compass", "Wojak"), 3, "Culture", Difficulty.HARD, explanation = "Wojak est devenu un mème politique car son visage générique et triste est utilisé pour représenter diverses positions idéologiques, souvent dans des dialogues satiriques en ligne."),
        Question(51488, "Quel est le mème internet le plus philosophique?", listOf("Rickroll", "Doge", "Existential Dread", "Deep Lore"), 2, "Culture", Difficulty.HARD, explanation = "Le mème \"Existential Dread\" représente un chien husky dont les propos absurdes et angoissés reflètent des questionnements philosophiques sur le sens de la vie, devenant viral pour son humour noir et son introspection."),
        Question(51489, "Quel carnaval a le plus de masques?", listOf("Rio", "Venise", "La Nouvelle-Orléans", "Trinidad"), 1, "Culture", Difficulty.HARD, explanation = "Le Carnaval de Venise est célèbre dans le monde entier pour ses masques élaborés et son atmosphère historique, attirant des milliers de participants costumés."),
        Question(51490, "Quel carnaval dépense le plus d'argent?", listOf("Rio", "Venise", "La Nouvelle-Orléans", "Trinidad"), 0, "Culture", Difficulty.HARD, explanation = "Le carnaval de Rio de Janeiro est le plus dépensier au monde, avec des investissements massifs des écoles de samba et de la ville pour les défilés, chars et costumes."),
        Question(51491, "Quel danse traditionnelle représente l'amour?", listOf("Ballet", "Flamenco", "Tango", "Valse"), 2, "Culture", Difficulty.MEDIUM, explanation = "Le tango est né dans les quartiers populaires de Buenos Aires et Montevideo, où il exprimait la passion et la nostalgie des immigrants, devenant un symbole universel de l'amour et de la séduction à travers sa gestuelle intime et sensuelle."),
        Question(51492, "Quel danse traditionnelle représente la colère?", listOf("Flamenco", "Ballet", "Tango", "Opéra"), 0, "Culture", Difficulty.MEDIUM, explanation = "Le flamenco, originaire d'Andalousie, exprime des émotions intenses comme la colère à travers ses mouvements brusques et son jeu de pieds percutant."),
        Question(51493, "Quel religion est la plus universelle?", listOf("Bouddhisme", "Christianisme", "Islam", "Hindouisme"), 1, "Culture", Difficulty.HARD, explanation = "Le christianisme est considéré comme la religion la plus universelle car elle est pratiquée sur tous les continents et compte environ 2,4 milliards de fidèles dans le monde."),
        Question(51494, "Quel religion est la plus fermée?", listOf("Jaïnisme", "Zoroastrisme", "Shintoïsme", "Judaïsme"), 3, "Culture", Difficulty.HARD, explanation = "Le judaïsme est souvent considéré comme la religion la plus fermée car il ne cherche pas activement à convertir les non-juifs et l'appartenance se transmet principalement par la naissance ou une conversion stricte."),
        Question(51495, "Quel site UNESCO a le meilleur accès?", listOf("Taj Mahal", "Big Ben", "Statue de la Liberté", "Colosseum"), 3, "Culture", Difficulty.HARD, explanation = "Le Colisée de Rome bénéficie d'un accès privilégié grâce à sa situation en centre-ville et à un système de réservation en ligne très efficace."),
        Question(51496, "Quel site UNESCO est le plus difficile d'accès?", listOf("Machu Picchu", "Bamiyan", "Knossos", "Angkor Wat"), 0, "Culture", Difficulty.HARD, explanation = "Perché à 2 430 mètres d'altitude dans les Andes péruviennes, le Machu Picchu n'est accessible qu'après une randonnée de plusieurs jours ou un trajet en train puis en bus. Son isolement géographique en fait le site UNESCO le plus difficile d'accès."),
        Question(51497, "Quel culture indigène a la plus longue tradition?", listOf("Mayas", "Égyptiens", "Australiens Aborigènes", "Chinois"), 2, "Culture", Difficulty.HARD, explanation = "Les Australiens Aborigènes possèdent la plus longue tradition culturelle continue au monde, avec des preuves archéologiques remontant à plus de 65 000 ans."),
        Question(51498, "Quel festival internet a le plus de documentation?", listOf("Twitch Plays", "Reddit Place", "4chan Raids", "Decentraland"), 2, "Culture", Difficulty.HARD, explanation = "Les raids de 4chan, notamment les opérations coordonnées sur d'autres sites, ont généré une vaste documentation en raison de leur impact médiatique et de leur analyse académique."),
        Question(51499, "Quel est le mème internet le plus sympathique?", listOf("Rickroll", "Doge", "Wholesome", "Good Boy"), 2, "Culture", Difficulty.HARD, explanation = "Wholesome désigne en anglais ce qui est sain, réconfortant et positif. Sur internet, ce terme qualifie les mèmes et contenus bienveillants qui diffusent de la bonne humeur."),
        Question(51500, "Quel est le mème internet le plus triste?", listOf("Rickroll", "Doge", "Loss", "F in Chat"), 3, "Culture", Difficulty.HARD, explanation = "F in Chat vient du jeu Call of Duty: Advanced Warfare, où un personnage demande de rendre hommage lors d’un enterrement, et le joueur doit appuyer sur la touche F. Cela est devenu un mème pour exprimer du respect ou de la tristesse.")
    )

