        Question(51509, "En quel année Roger Federer a-t-il remporté Wimbledon 8 fois?", listOf("2010", "2012", "2017", "2019"), 2, "Sport", Difficulty.HARD, explanation = "Roger Federer a remporté son huitième titre à Wimbledon en 2017, battant Marin Čilić en finale. Ce record faisait de lui le joueur le plus titré de l'histoire du tournoi."),
        Question(51510, "Quel est le record du monde de saut à ski?", listOf("253m", "263m", "273m", "283m"), 2, "Sport", Difficulty.HARD, explanation = "Le record du monde de saut à ski est détenu par Stefan Kraft avec un saut de 253,5 mètres, mais le record officiel le plus long est de 273 mètres, réalisé par Daniel-André Tande en 2015."),
        Question(51511, "Quel réalisateur a remporté l'Oscar du meilleur réalisateur pour 'Everything Everywhere All at Once'?", listOf("Paul Thomas Anderson", "Daniel Kwan et Daniel Scheinert", "Bong Joon-ho", "Quentin Tarantino"), 1, "Cinéma", Difficulty.MEDIUM, explanation = "Le duo connu sous le nom de Daniels a remporté l'Oscar du meilleur réalisateur en 2023 pour ce film, marquant la première fois qu'un duo remporte ce prix."),
        Question(51512, "Quel film a remporté le Golden Lion à Venise en 2023?", listOf("Past Lives", "The Iron Claw", "The Iron Claw", "The History of Light"), 0, "Cinéma", Difficulty.HARD, explanation = "Past Lives, réalisé par Celine Song, a reçu le Lion d'or à la 80e Mostra de Venise en 2023, distinguant ce drame romantique sur les choix de vie et les amours perdus."),
        Question(51513, "Quel compositeur a créé la musique de 'The Creator'?", listOf("Hans Zimmer", "Volker Bertelmann", "Volker Bertelmann", "Ludwig Göransson"), 1, "Cinéma", Difficulty.HARD, explanation = "Volker Bertelmann, également connu sous le nom de Hauschka, a composé la bande originale de ce film de science-fiction de 2023 réalisé par Gareth Edwards."),
        Question(51514, "Quel est le film le plus cher jamais produit?", listOf("Avatar 2", "Avengers: Endgame", "Pirates des Caraïbes: On Stranger Tides", "Tous les trois"), 2, "Cinéma", Difficulty.HARD, explanation = "Avec un budget estimé à 378,5 millions de dollars, ce quatrième volet de la franchise a détrôné le précédent record détenu par un autre film de la série."),
        Question(51515, "Quel réalisateur a réalisé 'Killers of the Flower Moon'?", listOf("Martin Scorsese", "David Fincher", "Christopher Nolan", "Quentin Tarantino"), 0, "Cinéma", Difficulty.MEDIUM, explanation = "Scorsese a adapté le livre-enquête de David Grann sur les meurtres des Osages dans les années 1920, avec une distribution comprenant Leonardo DiCaprio et Robert De Niro."),
        Question(51516, "Quel compositeur a créé la musique d'Oppenheimer?", listOf("Ludwig Göransson", "Hans Zimmer", "John Williams", "Ennio Morricone"), 0, "Cinéma", Difficulty.MEDIUM, explanation = "Ludwig Göransson a composé la bande originale d'Oppenheimer, réalisé par Christopher Nolan, avec qui il collabore régulièrement depuis Tenet."),
        Question(51517, "Quel album de Taylor Swift a remporté le plus de Grammys?", listOf("Folklore", "Evermore", "Fearless (Taylor's Version)", "Midnights"), 3, "Musique", Difficulty.HARD, explanation = "Midnights a remporté quatre Grammy Awards, dont celui de l'Album de l'année en 2024, ce qui en fait l'album le plus récompensé de Taylor Swift aux Grammys."),
        Question(51518, "Quel est le single le plus écouté au monde?", listOf("Blinding Lights", "Shape of You", "Someone Like You", "Uptown Funk"), 0, "Musique", Difficulty.HARD, explanation = "Blinding Lights de The Weeknd est le single le plus écouté sur Spotify, cumulant plus de 4 milliards de streams depuis sa sortie en 2019."),
        Question(51519, "Quel artiste a le plus d'écoutes sur Spotify?", listOf("The Weeknd", "Ed Sheeran", "Dua Lipa", "Billie Eilish"), 0, "Musique", Difficulty.MEDIUM, explanation = "The Weeknd est l'artiste le plus écouté sur Spotify grâce au succès massif de ses titres comme Blinding Lights et Save Your Tears, cumulant plus de 100 millions d'auditeurs mensuels."),
        Question(51520, "Quel est le prix Grammy remporté le plus de fois?", listOf("Meilleur Album", "Meilleur Disque", "Meilleure Chanson", "Artiste Révélation"), 0, "Musique", Difficulty.HARD, explanation = "Le Grammy du Meilleur Album est la catégorie la plus prestigieuse des Grammy Awards, récompensant l'ensemble d'un album. Des artistes comme Stevie Wonder, Paul Simon ou Taylor Swift l'ont remporté plusieurs fois."),
        Question(51521, "Quel album a vendu le plus de copies en 2023?", listOf("1989 (Taylor's Version)", "Midnights", "GUTS", "Speak Now (Taylor's Version)"), 0, "Musique", Difficulty.HARD, explanation = "En 2023, 1989 (Taylor's Version) de Taylor Swift a été l'album le plus vendu grâce à sa réédition très attendue, qui a attiré à la fois les fans originaux et une nouvelle génération."),
        Question(51522, "Quel empire a dominé le plus longtemps?", listOf("Romain", "Chinois", "Ottoman", "Britannique"), 1, "Histoire", Difficulty.HARD, explanation = "L'empire chinois, sous différentes dynasties, a perduré pendant plus de deux millénaires, de la dynastie Qin (221 av. J.-C.) à la fin de l'ère impériale en 1912, ce qui en fait le plus long empire continu de l'histoire."),
