        Question(51527, "Quel scientifique a remporté le plus de prix Nobel?", listOf("Marie Curie", "Linus Pauling", "Frederick Sanger", "John Bardeen"), 1, "Science", Difficulty.HARD, explanation = "Linus Pauling a remporté le prix Nobel de chimie en 1954 et le prix Nobel de la paix en 1962, ce qui fait de lui la seule personne à avoir reçu deux prix Nobel non partagés."),
        Question(51528, "Quel est le plus grand pays du monde?", listOf("Canada", "Chine", "États-Unis", "Russie"), 3, "Géographie", Difficulty.EASY, explanation = "La Russie est le plus vaste pays du monde avec une superficie d'environ 17,1 millions de kilomètres carrés, couvrant onze fuseaux horaires."),
