        Question(51531, "Quel carnaval dure le plus longtemps au monde?", listOf("Rio", "Venise", "La Nouvelle-Orléans", "Trinidad"), 0, "Culture", Difficulty.HARD, explanation = "Le carnaval de Rio dure officiellement cinq jours, mais les festivités s'étendent souvent sur plusieurs semaines avant le Mardi Gras, ce qui en fait l'un des plus longs au monde."),
