        Question(51533, "Quel religion a le plus de fidèles en Afrique?", listOf("Christianisme", "Islam", "Animisme", "Hindouisme"), 0, "Culture", Difficulty.MEDIUM, explanation = "Le christianisme est la religion majoritaire en Afrique, avec environ 50% de la population, devant l'islam qui représente environ 40%."),
        Question(51534, "Quel festival internet a le plus changé la culture?", listOf("Twitch Plays", "Reddit Place", "4chan Raids", "Metaverse"), 0, "Culture", Difficulty.HARD, explanation = "Twitch Plays Pokémon a démontré la puissance du jeu collaboratif de masse en ligne, influençant durablement la culture du streaming et des expériences participatives."),
