        Question(51546, "Quel est le plus grand sportif du football?", listOf("Pelé", "Maradona", "Messi", "Ronaldo"), 2, "Sport", Difficulty.HARD, explanation = "Messi a remporté huit Ballons d'Or, un record, et a mené l'Argentine à la victoire en Coupe du monde 2022, ce qui renforce son statut de plus grand footballeur pour beaucoup."),
