        Question(51548, "Quel est le plus grand nombre de Ballon d'Or remportés par un footballeur?", listOf("7", "8", "9", "10"), 1, "Sport", Difficulty.MEDIUM, explanation = "Lionel Messi détient le record avec 8 Ballons d'Or, le dernier obtenu en 2023. Il devance Cristiano Ronaldo, qui en compte 5."),
