        Question(51550, "Quel est l'album le plus vendu de tous les temps?", listOf("Thriller", "Back in Black", "The Dark Side of the Moon", "Abbey Road"), 0, "Musique", Difficulty.EASY, explanation = "Sorti en 1982, l'album Thriller de Michael Jackson est certifié 33 fois disque de platine aux États-Unis et s'est vendu à plus de 100 millions d'exemplaires dans le monde."),
