        Question(51556, "En quelle année l'Afrique du Sud a-t-elle remporté la Coupe du Monde de rugby?", listOf("1995", "2007", "2019", "2023"), 0, "Sport", Difficulty.MEDIUM, explanation = "L'Afrique du Sud a remporté la Coupe du Monde de rugby en 1995, un an après la fin de l'apartheid, en battant la Nouvelle-Zélande en finale à Johannesburg."),
        Question(51557, "Quel est le plus grand événement sportif du monde?", listOf("Coupe du Monde", "Jeux Olympiques", "Tour de France", "Super Bowl"), 1, "Sport", Difficulty.MEDIUM, explanation = "Les Jeux Olympiques rassemblent plus de 200 nations et des milliers d'athlètes dans une compétition multisports tous les quatre ans, ce qui en fait l'événement sportif le plus suivi et médiatisé au monde."),
